def subtree_with_all_deepest(root):
    parent, level = {root: None}, [root]
    while True:
        nxt = []
        for node in level:
            for child in (node.left, node.right):
                if child is not None:
                    parent[child] = node
                    nxt.append(child)
        if not nxt:
            break
        level = nxt
    group = set(level)                  # the deepest nodes
    while len(group) > 1:
        group = {parent[n] for n in group}
    return group.pop()

def subtree_with_all_deepest(root):
    def dfs(node):
        if node is None:
            return 0, None
        ld, la = dfs(node.left)
        rd, ra = dfs(node.right)
        if ld == rd:
            return ld + 1, node
        return (ld + 1, la) if ld > rd else (rd + 1, ra)

    return dfs(root)[1]
